// Generated by ../../import_fabrics.py; outfit constraints are original.
use rand::{Rng, rngs::StdRng};

const PALETTES: [(&str, &str, &str, &str); 10] = [
    ("ivory", "navy", "rust", "dark brown"),
    ("stone", "charcoal", "forest green", "black"),
    ("cream", "olive", "terracotta", "dark brown"),
    ("pale blue", "navy", "burgundy", "dark brown"),
    ("light gray", "black", "cobalt", "black"),
    ("white", "indigo", "ochre", "tan"),
    ("ecru", "chocolate", "sage", "dark brown"),
    ("oatmeal", "slate", "plum", "black"),
    ("sand", "espresso", "teal", "dark brown"),
    ("pearl gray", "midnight blue", "muted coral", "black"),
];
const TOPS: &[&str] = &[
    "long-sleeve merino base layer",
    "long-sleeve moisture-wicking polyester base layer",
];
const BOTTOMS: &[&str] = &[
    "quick-drying nylon ripstop hiking trousers",
    "quick-drying polyester hiking trousers",
];
const SHOES: &[&str] = &["waterproof hiking boots", "waterproof trail shoes"];
const MIDDLE: &[&str] = &["insulating polar fleece", "insulating wool sweater"];

fn choose<'a>(rng: &mut StdRng, options: &[&'a str]) -> &'a str {
    options[rng.random_range(0..options.len())]
}

pub fn generate(rng: &mut StdRng) -> String {
    let (light, dark, accent, leather) = PALETTES[rng.random_range(0..PALETTES.len())];
    let temperature = rng.random_range(0..=8);
    let shoe_color = dark;
    let _ = leather;
    let mut lines = vec![
        format!("Day hike on maintained trails; cold and dry, {temperature} C."),
        format!("Top: {light} {}.", choose(rng, TOPS)),
        format!("Bottom: {dark} {}.", choose(rng, BOTTOMS)),
    ];
    lines.push(format!("Middle layer: {accent} {}.", choose(rng, MIDDLE)));
    lines.push(format!(
        "Outer layer: {dark} insulated wind-resistant hiking jacket sized over the middle layer."
    ));
    lines.push(format!("Footwear: {shoe_color} {}.", choose(rng, SHOES)));
    lines.push("Accessories: warm beanie, gloves, and wool hiking socks.".to_owned());

    lines.join("\n")
}

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;
    use std::collections::HashSet;

    #[test]
    fn scenario_constraints_and_actual_palette_items() {
        let mut rng = StdRng::seed_from_u64(31);
        let mut outputs = HashSet::new();
        for _ in 0..500 {
            let text = generate(&mut rng);
            assert!(text.contains("Middle layer:") && text.contains("insulated"));
            assert!(text.contains("gloves") && !text.contains("shorts"));
            assert!(
                text.contains("base layer") && (text.contains("hiking") || text.contains("trail"))
            );
            let matched = PALETTES.iter().any(|(light, dark, accent, leather)| {
                let _ = leather;
                text.contains(&format!("Top: {light} "))
                    && text.contains(&format!("Bottom: {dark} "))
                    && text.contains(&format!("{}: {accent} ", "Middle layer"))
                    && text.contains(&format!("Footwear: {} ", dark))
            });
            assert!(matched, "{text}");
            assert!(!text.ends_with('\n'));
            outputs.insert(text);
        }
        assert!(outputs.len() > 150);
    }
}
